<template>
  <div class="container">
    <h1>Random Quote Generator</h1>
   
    <p v-if="loading">Loading...</p>
    <p v-else class="quote-text">
      "{{ quote }}" <br>
      <em v-if="author">- {{ author }}</em>
    </p>
    
    <button @click="getQuote" class="quote-btn">Get New Quote</button>
    
    <!-- Add Go Back button -->
    <GoBackButton />
  </div>
</template>

<script>
import axios from 'axios';
import GoBackButton from '../components/GoBackButton.vue';

export default {
  name: 'RandomQuotes',
  components: {
    GoBackButton
  },
  data() {
    return {
      quote: '',      
      author: '',    
      loading: false  
    };
  },
  methods: {
    async getQuote() {
      this.loading = true;
      try {
        // Send a GET request to the Quotable API
        const response = await axios.get('https://quotes15.p.rapidapi.com/quotes/random/?language_code=en', {
          headers: {
            'x-rapidapi-host': 'quotes15.p.rapidapi.com',
            'x-rapidapi-key': 'c972a3b012msh95b275ac6f315c4p108d1cjsn545aff49326d'
          }
        });
        
        this.quote = response.data.content;
        this.author = response.data.originator.name;
      } catch (error) {
        console.error('Error fetching quote:', error);
        this.quote = 'Oops! Something went wrong.';
        this.author = '';
      } finally {
        this.loading = false;
      }
    }
  },
  mounted() {
    // Load a quote when the component is mounted
    this.getQuote();
  }
};
</script>

